    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '241: A 32-year-old at 39 weeks presents with painful, regular contractions every 3 minutes. Cervix is 5 cm, 100% effaced, and 0 station. FHR is 140 with moderate variability. Diagnosis?', '["Latent phase of labor", "Active phase of labor", "Precipitous labor", "False labor"]', 1, 'Regular contractions with significant cervical change (5 cm) indicates active labor. (Williams)'),
    (v_topic_id, '242: In the same patient, 4 hours later, the cervix is still 5 cm. IUPC shows 150 MVUs. Next best step?', '["Immediate C-section", "Wait 2 more hours", "Amniotomy and Oxytocin augmentation", "Manual rotation"]', 2, 'Contractions are inadequate (< 200 MVUs) and no progress has been made; augmentation is indicated. (ACOG)'),
    (v_topic_id, '243: A 28-year-old G1P0 at 40 weeks has been pushing for 3 hours with an epidural. Fetus is OA at +2 station. What is the diagnosis?', '["Normal stage 2", "Prolonged second stage", "Arrest of dilation", "Precipitous labor"]', 1, 'Stage 2 is prolonged after 3 hours with an epidural in a nullipara. (ACOG)'),
    (v_topic_id, '244: What is the most common cause of "Prolonged Second Stage"?', '["Large baby", "Fetal malposition (e.g., OP)", "Small pelvis", "Maternal age"]', 1, 'Occiput Posterior or Transverse positions often slow down descent. (Beckmann)'),
    (v_topic_id, '245: A G2P1 at 38 weeks delivers a 4200g baby. After placental delivery, she has heavy vaginal bleeding and a soft, boggy uterus. First step?', '["Manual exploration", "Bimanual uterine massage and IV Oxytocin", "Hysterectomy", "Pack the vagina"]', 1, 'Initial management of atony is massage and uterotonics. (ACOG)'),
    (v_topic_id, '246: If the patient in the previous question has a BP of 160/100, which medication should be AVOIDED?', '["Oxytocin", "Misoprostol", "Methylergonovine (Methergine)", "Hemabate"]', 2, 'Methergine is contraindicated in hypertension. (Williams)'),
    (v_topic_id, '247: If the patient instead had a history of severe Asthma, which medication should be AVOIDED?', '["Oxytocin", "Methergine", "Carboprost (Hemabate)", "Misoprostol"]', 2, 'Hemabate can cause bronchoconstriction. (Beckmann)'),
    (v_topic_id, '248: A woman at 30 weeks presents with "gush of fluid." Nitrazine and Fern tests are positive. She has no contractions. Diagnosis?', '["PROM", "PPROM", "Preterm labor", "Urinary incontinence"]', 1, 'Preterm Premature Rupture of Membranes (before 37 weeks and before labor). (ACOG)'),
    (v_topic_id, '249: Management of PPROM at 30 weeks with no signs of infection?', '["Immediate delivery", "Expectant management with antibiotics, steroids, and magnesium (if < 32w)", "Tocolytics for 1 month", "Bed rest only"]', 1, 'Goal is to prolong pregnancy safely to reduce prematurity risks. (ACOG)'),
    (v_topic_id, '250: At what gestational age is "Delivery" generally recommended for PPROM?', '["32 weeks", "34 weeks", "36 weeks", "37 weeks"]', 1, 'Risks of infection outweigh risks of prematurity after 34 weeks. (ACOG)'),
    (v_topic_id, '251: A patient at 42 weeks has an AFI of 3 cm. Next step?', '["Repeat AFI in 1 week", "Induction of labor", "C-section", "Bed rest"]', 1, 'Oligohydramnios in post-term pregnancy is an indication for delivery. (Williams)'),
    (v_topic_id, '252: "Bishop Score" includes: Dilation, Effacement, Station, Position, and:', '["Consistency", "Fetal heart rate", "Maternal age", "Weight"]', 0, 'Cervical consistency (soft, medium, firm). (Beckmann)'),
    (v_topic_id, '253: A Bishop score of 3 in a nullipara at 41 weeks. Best method for induction?', '["Oxytocin alone", "Cervical ripening with prostaglandins (PGE2) or mechanical dilator", "Amniotomy", "Wait 1 week"]', 1, 'An unripe cervix needs ripening before oxytocin. (ACOG)'),
    (v_topic_id, '254: Mechanical cervical ripening includes:', '["Foley bulb catheter", "Laminaria", "Both", "None"]', 2, 'Foley bulb provides pressure and stimulates endogenous prostaglandins. (Williams)'),
    (v_topic_id, '255: After a Foley bulb is placed for ripening, when is it typically removed?', '["When it falls out (usually at 3-4 cm) or after 12 hours", "After 24 hours", "When labor starts", "Only in the OR"]', 0, 'Safe and effective method. (Beckmann)'),
    (v_topic_id, '256: A "Non-stress test" (NST) is "Reactive" if there are:', '["2 accelerations in 20 minutes", "1 acceleration in 10 minutes", "No decelerations", "Moderate variability only"]', 0, 'Standard criteria for fetal well-being. (ACOG)'),
    (v_topic_id, '257: A "Contraction Stress Test" (CST) is "Positive" (abnormal) if:', '["There are no decelerations", "Late decelerations occur with more than 50% of contractions", "Early decelerations occur", "Accelerations are present"]', 1, 'Indicates uteroplacental insufficiency. (Williams)'),
    (v_topic_id, '258: Which of the following is a "Minor" risk factor for PPH?', '["Multiple gestation", "Asian or Hispanic ethnicity", "Prior PPH", "Obesity"]', 1, 'Ethnicity is a recognized statistical risk factor. (Beckmann)'),
    (v_topic_id, '259: The "B-Lynch" suture is most similar to which item in function?', '["A seatbelt", "A pair of suspenders compressing the uterus", "A tourniquet", "A zipper"]', 1, 'A physical description often used to explain the compression technique. (Williams)'),
    (v_topic_id, '260: In "Active Phase Protraction," what is the most appropriate management?', '["Immediate C-section", "Amniotomy and Oxytocin augmentation", "Wait and watch", "Forceps"]', 1, 'Aimed at achieving adequate contraction pattern. (ACOG)'),
    (v_topic_id, '261: "Maternal Exhaustion" is an indication for:', '["Instrumental vaginal delivery (if criteria met)", "C-section", "Wait longer", "More IV fluids"]', 0, 'If the head is low enough, forceps or vacuum can help. (Beckmann)'),
    (v_topic_id, '262: "Umbilical Cord Gas" showing pH < 7.0 and Base Deficit > 12 is diagnostic of:', '["Normal baby", "Severe fetal metabolic acidosis", "Respiratory acidosis", "Infection"]', 1, 'Suggests a significant hypoxic event. (Williams)'),
    (v_topic_id, '263: "Respiratory Acidosis" in the cord gas (Low pH, High pCO2) is usually due to:', '["Chronic placental failure", "Acute cord compression (transient)", "Infection", "Diabetes"]', 1, 'Carbon dioxide builds up because it cannot be cleared through the cord. (Beckmann)'),
    (v_topic_id, '264: Which "Laceration" repair involves the internal and external anal sphincter?', '["1st degree", "2nd degree", "3rd degree", "4th degree"]', 2, '3rd degree is subdivided into 3a, 3b, 3c based on how much of the sphincter is torn. (Williams)'),
    (v_topic_id, '265: "Episiotomy" types include Midline and:', '["Lateral", "Mediolateral", "Superior", "Circular"]', 1, 'Mediolateral has lower risk of 4th-degree extension but more pain. (Beckmann)'),
    (v_topic_id, '266: "Placenta Accreta" risk increases with:', '["Number of prior C-sections", "History of placenta previa", "Maternal age", "Both A and B"]', 3, 'Prior C-section + current Previa = very high risk. (ACOG)'),
    (v_topic_id, '267: Management of confirmed "Placenta Accreta" at term?', '["Vaginal delivery", "Planned Cesarean-Hysterectomy", "Forceps", "Induction"]', 1, 'To avoid the catastrophic bleeding that occurs when trying to remove the placenta. (ACOG)'),
    (v_topic_id, '268: "Amniotic Fluid Embolism" (AFE) often occurs:', '["In the 1st trimester", "During labor or immediately postpartum", "At 20 weeks", "Only in twins"]', 1, 'Sudden collapse with DIC and ARDS. (Williams)'),
    (v_topic_id, '269: First-line management of AFE is:', '["Antibiotics", "Aggressive supportive care (A-OK protocol: Atropine, Ondansetron, Ketorolac)", "C-section", "Oxytocin"]', 1, 'Supportive care is the only treatment. (Beckmann)'),
    (v_topic_id, '270: "Uterine Atony" that is refractory to meds and balloon tamponade may require:', '["Uterine Artery Embolization or Ligation", "Hysterectomy", "B-Lynch suture", "All of the above"]', 3, 'Steps in the PPH algorithm. (Williams)'),
    (v_topic_id, '271: "Postpartum Thyroiditis" differs from Graves disease by having:', '["High uptake on radioactive iodine scan", "Low uptake on radioactive iodine scan", "Eye changes (exophthalmos)", "Goiter"]', 1, 'Due to release of pre-formed hormone, not new synthesis. (Beckmann)'),
    (v_topic_id, '272: "Postpartum Urinary Retention" is common after:', '["Epidural and instrumental delivery", "C-section", "Quick labor", "No anesthesia"]', 0, 'May require temporary catheterization. (Williams)'),
    (v_topic_id, '273: Which hormone inhibits the effect of Prolactin on the breast during pregnancy?', '["Estrogen", "Progesterone", "hCG", "Both A and B"]', 3, 'Falling levels of these after placental delivery allows milk production to start. (Beckmann)'),
    (v_topic_id, '274: "Engorgement" pain can be relieved by:', '["Nursing", "Cabbage leaves (cool)", "NSAIDs", "All of the above"]', 3, 'Common nursing advice. (Williams)'),
    (v_topic_id, '275: "Mastitis" should be suspected if fever occurs after day _____ postpartum.', '["1", "2", "7", "42"]', 2, 'Early fevers are more likely to be endometritis. (Beckmann)'),
    (v_topic_id, '276: A woman with "Chorioamnionitis" delivered vaginally 2 hours ago. She now has a fever of 103F and tender uterus. Next step?', '["Wait for it to resolve", "Continue IV Antibiotics until she is afebrile for 24 hours", "Stop antibiotics", "Oral meds only"]', 1, 'Standard of care for postpartum endometritis/chorio. (Williams)'),
    (v_topic_id, '277: "Septic Pelvic Thrombophlebitis" (SPT) is essentially:', '["An infected blood clot in the pelvic veins", "A leg DVT", "A skin infection", "Uterine cancer"]', 0, 'Associated with persistent fever. (Beckmann)'),
    (v_topic_id, '278: "Hemorrhagic Shock" in PPH is often "masked" because:', '["Pregnant women have 50% increased blood volume and can lose 1-2L before BP drops", "BP is always high in labor", "Mothers don''t feel pain", "None"]', 0, 'Tachycardia and narrowed pulse pressure are earlier signs. (Williams)'),
    (v_topic_id, '279: "Massive Transfusion Protocol" (MTP) in OB usually uses a ratio of RBC:FFP:Platelets of:', '["1:1:1", "4:1:1", "2:1:1", "1:0:0"]', 0, 'Aimed at preventing "lethal triad" of acidosis, coagulopathy, and hypothermia. (ACOG)'),
    (v_topic_id, '280: "Delayed Cord Clamping" in PRETERM infants reduces the risk of:', '["Intraventricular Hemorrhage (IVH) and NEC", "Jaundice", "Infection", "Hypoglycemia"]', 0, 'Provides more blood volume and iron. (ACOG)'),
    (v_topic_id, '281: Which FHR pattern is a classic sign of "Fetal Sleep"?', '["Late decelerations", "Minimal variability with no accelerations for 20-40 min", "Tachycardia", "Sinusoidal"]', 1, 'Wait 40 minutes before calling it "non-reactive." (Williams)'),
    (v_topic_id, '282: "Fetal Scalp Stimulation" is used to:', '["Wake the baby", "Evoke an acceleration (proves pH > 7.20)", "Test for hair", "Check for caput"]', 1, 'If the baby accelerates, they are not acidotic. (Beckmann)'),
    (v_topic_id, '283: "Vibroacoustic Stimulation" (VAS) is used during:', '["Labor", "NST (to evoke accelerations)", "C-section", "Delivery"]', 1, 'Short sound/vibration applied to maternal abdomen. (ACOG)'),
    (v_topic_id, '284: If a patient has "Severe Pre-eclampsia" at 34 weeks, management?', '["Wait until 37 weeks", "Stabilize and deliver (usually induction)", "Bed rest for 6 weeks", "None"]', 1, 'Severe features warrant delivery after 34 weeks. (ACOG)'),
    (v_topic_id, '285: "Eclampsia" is defined by:', '["High BP", "Proteinuria", "Grand mal seizures in the setting of pre-eclampsia", "Headache"]', 2, 'Medical emergency; requires airway protection and Magnesium. (Williams)'),
    (v_topic_id, '286: Management of Eclamptic Seizure?', '["Immediate C-section DURING the seizure", "Stabilize mother (Magnesium, Airway) and then deliver once she is stable", "Wait until 40 weeks", "None"]', 1, 'Never rush to the OR during a seizure; let the mother and fetus recover first. (ACOG)'),
    (v_topic_id, '287: "HELLP" syndrome is a variant of:', '["Diabetes", "Pre-eclampsia", "Infection", "Normal pregnancy"]', 1, 'Hemolysis, Elevated Liver enzymes, Low Platelets. (Beckmann)'),
    (v_topic_id, '288: "Platelet" count in HELLP is typically below:', '["100,000", "50,000", "150,000", "200,000"]', 0, 'Criterion for diagnosis. (Williams)'),
    (v_topic_id, '289: "Pruritic Urticarial Papules and Plaques of Pregnancy" (PUPPP) is:', '["Dangerous", "Extremely itchy rash on the abdomen (often in striae)", "A sign of liver failure", "Viral"]', 1, 'Benign but miserable; treated with steroids/antihistamines. (Beckmann)'),
    (v_topic_id, '290: "Intrahepatic Cholestasis of Pregnancy" (ICP) is characterized by:', '["Rash", "Intense itching (especially palms/soles) and elevated bile acids", "High BP", "Fever"]', 1, 'Increased risk of stillbirth; deliver at 36-37 weeks. (ACOG)'),
    (v_topic_id, '291: "Urinary Tract Infection" (UTI) in pregnancy is treated even if asymptomatic (Asymptomatic Bacteriuria) to prevent:', '["Diabetes", "Pyelonephritis and Preterm Labor", "Weight gain", "Twins"]', 1, 'Pregnancy increases risk of ascending infection. (Williams)'),
    (v_topic_id, '292: Most common cause of "Pyelonephritis" in pregnancy?', '["E. coli", "Staph", "Strep", "Yeast"]', 0, 'Requires hospitalization for IV fluids and antibiotics. (Beckmann)'),
    (v_topic_id, '293: "Group B Strep" status is valid for how many weeks?', '["1", "5", "10", "Whole pregnancy"]', 1, 'If > 5 weeks have passed since the 36-week swab, re-testing or empiric treatment is used. (CDC)'),
    (v_topic_id, '294: If a woman has a "Penicillin Allergy" (non-anaphylactic), what is the alternative for GBS?', '["Ceftriaxone", "Cefazolin", "Clindamycin (if sensitive)", "Vancomycin"]', 1, 'Cefazolin provides good coverage. (CDC)'),
    (v_topic_id, '295: "Clindamycin" can only be used for GBS if the isolate is:', '["Large", "Sensitive to both Clindamycin and Erythromycin (no D-zone)", "Resistant", "Pink"]', 1, 'Checking for "inducible" resistance. (CDC)'),
    (v_topic_id, '296: "Listeriosis" in pregnancy is usually caused by:', '["Cat litter", "Contaminated deli meats or unpasteurized cheese", "Dogs", "Air"]', 1, 'Can cause miscarriage, stillbirth, or neonatal sepsis. (Williams)'),
    (v_topic_id, '297: "Toxoplasmosis" is associated with:', '["Undercooked meat and Cat feces", "Cheese", "Water", "Fish"]', 0, 'Can cause fetal brain calcifications and chorioretinitis. (Beckmann)'),
    (v_topic_id, '298: "Parvovirus B19" (Fifth Disease) "slapped-cheek" rash in the mother indicates risk of:', '["Fetal heart failure (Hydrops)", "Fetal limb defects", "Cataracts", "Deafness"]', 0, 'Fetal anemia is the primary mechanism. (Williams)'),
    (v_topic_id, '299: "Cytomegalovirus" (CMV) is the most common congenital infection and often causes:', '["Heart defects", "Sensorineural hearing loss and periventricular calcifications", "Limb hypoplasia", "Diabetes"]', 1, 'Most infants are asymptomatic at birth. (Beckmann)'),
    (v_topic_id, '300: "Congenital Rubella Syndrome" triad includes Cataracts, Heart defects, and:', '["Deafness", "Diabetes", "Rash", "Limb loss"]', 0, 'Highest risk in the 1st trimester. (Williams)');
